/**
 * Sales Operating System Audit — question bank.
 *
 * Single source of truth for every question, field, option, skip rule and SOP tag.
 * Generated from "Sales_Operating_System_Audit1.docx" (20 Oct 2026), 273 questions.
 *
 * PERMANENCE RULES (never break these once live):
 *  - `id` on a question is permanent. Answers are stored against it. Never change or reuse an id.
 *    `number` is display-only and may change.
 *  - Field `key`s, list `itemFields` keys, linked `rowFields` keys and option `key`s are permanent.
 *    Labels may be reworded freely.
 *  - To retire a question, remove it from QUESTIONS; never reassign its id.
 *
 * FIELD TYPES
 *  number   numeric input; `unit` decides formatting. Every number field has an "Estimate" tick box.
 *  text     multi-line free text.
 *  script   larger text area for pasting exact wording.
 *  choice   pick one. `allowOther` adds "Other" + text box.
 *  multi    tick any. `allowOther` adds "Other" + text box. An option with `exclusive: true`
 *           (e.g. "None") clears all others when ticked, and is cleared when any other is ticked.
 *  yesno    two buttons; stored as "yes" | "no".
 *  upload   files and/or links. `slots` = labelled single-item slots (e.g. Won / Lost / Still open);
 *           without slots the founder can add any number of files and links.
 *  list     founder adds rows. Each row gets a permanent item id (crypto.randomUUID()).
 *           `itemFields` define the row; `maxItems` caps it; `reorderable` enables up/down arrows.
 *  linked   one row per item of `source` (a list field, or the ticked options of a multi field,
 *           including "Other" if ticked) in the SAME section. Rows keyed by item id / option key.
 *           `skipLastItem` omits the final list item (e.g. "% to next stage").
 *           `excludeOptions` omits those option keys (e.g. "none").
 *
 * VISIBILITY
 *  - Field `showWhen` refers to another field of the SAME question.
 *  - SKIP_RULES `when` refers to any question (by id). If any rule matches, its `hide` targets are
 *    hidden. "section:N" hides a whole section; a section with no visible questions is hidden.
 *  - Condition operators: eq, notEq, in, includes (multi has key), excludes (multi lacks key),
 *    all, any. A condition on an unanswered field (or one carrying a marker) is FALSE.
 *  - Hidden questions/fields keep their saved values but are excluded from progress and admin views.
 *
 * MARKERS
 *  markers "standard": "Don't know" and "We don't do this".  markers "upload": "We don't have this".
 *  A marker counts as answered.
 *
 * COMPLETION
 *  A visible question is answered when it has a marker, or its FIRST field has a value:
 *   - list: at least one item; linked: every row's first rowField has a value; upload: at least one
 *     file or link (in any slot); multi: at least one option ticked; others: non-empty.
 *  Further fields are optional. A section is complete when every visible question is answered.
 *
 * SOPS
 *  `sops` lists SOP ids this question feeds. "ALL" = feeds every SOP (shown under every SOP in admin).
 *
 * SCREENING
 *  Shown first. Each item renders the listed fields of an existing question; it is the SAME stored
 *  answer as the question's later appearance (shown pre-filled there, editable in both places).
 *  q0_1 is screening-only (`screeningOnly: true`) and never appears in a section.
 */

export type SosaUnit = 'money' | 'percent' | 'count' | 'days' | 'months' | 'years' | 'hours';

export interface SosaOption {
  key: string;
  label: string;
  exclusive?: boolean;
}

export type SosaCondition =
  | { all: SosaCondition[] }
  | { any: SosaCondition[] }
  | {
      /** Omitted inside a field's showWhen (= same question). Required in SKIP_RULES. */
      question?: string;
      field: string;
      eq?: string | number;
      notEq?: string | number;
      in?: string[];
      includes?: string;
      excludes?: string;
    };

interface SosaFieldBase {
  key: string;
  label?: string;
  showWhen?: SosaCondition;
}

export type SosaField =
  | (SosaFieldBase & { type: 'number'; unit?: SosaUnit })
  | (SosaFieldBase & { type: 'text' })
  | (SosaFieldBase & { type: 'script' })
  | (SosaFieldBase & { type: 'yesno' })
  | (SosaFieldBase & { type: 'choice'; options: SosaOption[]; allowOther?: boolean })
  | (SosaFieldBase & { type: 'multi'; options: SosaOption[]; allowOther?: boolean })
  | (SosaFieldBase & { type: 'upload'; slots?: { key: string; label: string }[] })
  | (SosaFieldBase & {
      type: 'list';
      itemLabel: string;
      itemFields: SosaField[];
      maxItems?: number;
      reorderable?: boolean;
    })
  | (SosaFieldBase & {
      type: 'linked';
      source: { question: string; field: string };
      rowFields: SosaField[];
      skipLastItem?: boolean;
      excludeOptions?: string[];
    });

export interface SosaQuestion {
  id: string;
  number: string;
  section: number;
  group?: string;
  prompt: string;
  hint?: string;
  sops: string[];
  markers: 'standard' | 'upload';
  screeningOnly?: boolean;
  fields: SosaField[];
}

export interface SosaSection {
  number: number;
  title: string;
  intro: string;
  note?: string;
}

export interface SosaSop {
  id: string;
  name: string;
}

export interface SosaScreeningItem {
  questionId: string;
  fields: string[];
  prompt: string;
}

export interface SosaSkipRule {
  label: string;
  when: SosaCondition;
  hide: string[];
}

